// Validate input for sending a WhatsApp Business Cloud API template message,
// and build the official template-message request body when valid.
//
// This sub-workflow is meant to be called via the Execute Workflow node from
// another n8n workflow (it uses an Execute Workflow Trigger, not a webhook).

const input = $input.first().json;

function isValidPhone(v) {
  // Plausible international, digits-only, no leading +, no leading 0.
  return typeof v === 'string' && /^[1-9]\d{7,14}$/.test(v);
}
function isValidTemplateName(v) {
  // Meta template names: lowercase letters, digits, underscores only.
  return typeof v === 'string' && v.length > 0 && v.length <= 512 && /^[a-z0-9_]+$/.test(v);
}
function isValidLanguageCode(v) {
  // e.g. "en", "en_US", "tr", "nl_NL"
  return typeof v === 'string' && /^[a-z]{2}(_[A-Z]{2})?$/.test(v);
}
function isValidBodyParameters(v) {
  if (v === undefined || v === null) return true;
  if (!Array.isArray(v)) return false;
  if (v.length > 10) return false;
  return v.every((p) => typeof p === 'string' && p.length > 0 && p.length <= 200);
}

const recipientPhone = input.recipientPhone;
const templateName = input.templateName;
const languageCode = input.languageCode;
const bodyParameters = input.bodyParameters;

const valid =
  isValidPhone(recipientPhone) &&
  isValidTemplateName(templateName) &&
  isValidLanguageCode(languageCode) &&
  isValidBodyParameters(bodyParameters);

if (!valid) {
  return [{ json: { _route: 'invalid' } }];
}

const components = [];
if (Array.isArray(bodyParameters) && bodyParameters.length > 0) {
  components.push({
    type: 'body',
    parameters: bodyParameters.map((text) => ({ type: 'text', text })),
  });
}

const requestBody = {
  messaging_product: 'whatsapp',
  to: recipientPhone,
  type: 'template',
  template: {
    name: templateName,
    language: { code: languageCode },
    components,
  },
};

return [{ json: { _route: 'valid', requestBody } }];

// The HTTP Request node is configured with "Never Error" + "Full Response",
// so this branch receives every HTTP response regardless of status code --
// this node classifies it into a controlled, non-sensitive result. It never
// forwards the raw response body/headers, the recipient number, or message
// content -- only status / httpStatus / providerMessageId.

const item = $input.first().json; // { statusCode, headers, body }
const statusCode = item.statusCode;
const body = (item.body && typeof item.body === 'object') ? item.body : {};

let status;
let providerMessageId = null;

if (statusCode >= 200 && statusCode < 300) {
  status = 'sent';
  const id = body.messages && body.messages[0] && body.messages[0].id;
  providerMessageId = typeof id === 'string' ? id : null;
} else if (statusCode === 401 || statusCode === 403) {
  status = 'auth_error';
} else if (statusCode === 429) {
  status = 'rate_limited';
} else if (statusCode >= 500) {
  status = 'provider_error';
} else if (statusCode === 400) {
  status = 'provider_rejected';
} else {
  status = 'provider_rejected';
}

return [{ json: { status, httpStatus: statusCode, providerMessageId } }];

// Reached only when the HTTP request itself could not complete (timeout,
// connection refused, DNS failure, etc.) -- not a real HTTP response, so no
// status code is available. Never forwards the raw error message or stack.

return [{ json: { status: 'timeout', httpStatus: null, providerMessageId: null } }];

// Input failed validation before any HTTP request was made. No provider was
// contacted, so there is no HTTP status or provider message ID.

return [{ json: { status: 'rejected', httpStatus: null, providerMessageId: null } }];
